import{_ as p,a0 as s,w as l,s as u,I as i,x as e,a1 as a,A as o,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"什麼時候Linux才能完美？ | LCTT x X-CMD","titleTemplate":false,"description":"什麼時候Linux才能完美？ | LCTT (201409) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"什麼時候Linux才能完美？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"什麼時候Linux才能完美？ | LCTT (201409) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201409/20140808 When Linux Was Perfect Enough","title":"什麼時候Linux才能完美？","tag":"201409","desc":""},"relativePath":"201409/20140808 When Linux Was Perfect Enough.md","filePath":"[post].md"}'),d={name:"201409/20140808 When Linux Was Perfect Enough.md"};function x(f,n,L,m,T,h){const t=s("Link");return l(),u("div",null,[n[17]||(n[17]=i("h1",{id:"什麼時候linux才能完美",tabindex:"-1"},[e("什麼時候Linux才能完美？ "),i("a",{class:"header-anchor",href:"#什麼時候linux才能完美","aria-label":"Permalink to “什麼時候Linux才能完美？”"},"​")],-1)),i("p",null,[n[1]||(n[1]=e("前幾天我的同事兼損友，Ken Starks，在FOSS Force上發表了",-1)),a(t,{href:"http://fossforce.com/2014/07/ripe-linux-nits-to-pick/"},{default:o(()=>[...n[0]||(n[0]=[e("一篇文章",-1)])]),_:1}),n[2]||(n[2]=e("，關於他最喜歡發牢騷的內容：Linux系統中那些不能正常工作的事情。這次他抱怨的是在Mint裏使用KDE時碰到的字體問題。這對於Ken來説也不是什麼新鮮事了。過去他寫了一些文章，關於各種Linux發行版中的缺陷從來都沒有被認真修復過。他的觀點是，這些在一次又一次的發佈中從沒有被修復過的“小問題”，對於Linux桌面系統在贏得大眾方面的失敗需要負主要責任。",-1))]),n[18]||(n[18]=r('<h3 id="他也許是對的" tabindex="-1">他也許是對的 <a class="header-anchor" href="#他也許是對的" aria-label="Permalink to “他也許是對的”">​</a></h3><p>聖誕節的時候，我給室友買了一個運行Android系統的二代Nexus 7平板，Android是一個建立在Linux內核基礎上的操作系統。它拿起來就“能用”，不需要任何的調整。在過去的7個月裏，她每天都要使用好幾個小時。據我所瞭解的，她沒發現任何需要修復的小問題。我敢肯定如果她碰到問題我會第一個知道，因為之前送給她Nexus的原因就是，我已經不想再繼續維護她的Windows筆記本去滿足她的需求了。她的電腦出問題後總是能找到我，而且總是希望我第一時間解決。Facebook不會等任何人，你懂的。</p><p>我説這個的原因是，Linux已經在計算機領域的手機和平板方面佔據了首要位置。Apple確實通過iPhone和iPad賺了很多錢，但那是因為他們定的高價。而在市場佔有率上，它遠遠比不上Android設備。而Microsoft也説明了Windows不再是過去那個無敵巨人。儘管花了大量的錢在電視廣告和幾乎CBS所有的連續劇中的顯眼位置，Windows移動設備在市場佔有率上看仍然僅僅只是個星號。</p><p>換句話説，Linux打贏了這場移動領域的戰爭。因為Google保證了Android拿起來就“能用”。</p><p>如今一般的計算機用户（我不喜歡“消費者”這個詞）希望用他們的計算機來完成工作，而不是深入到裏面去解決問題。這是可以理解的，就像一般擁有汽車的人，只是希望駕駛他們的汽車而不會想了解汽車的工作原理。就像大多數司機把他們的汽車送到修理店裏去解決機械或電子問題，大多數的計算機用户也會把他們的設備送去返修而不操心是硬件問題或軟件問題。他們只是希望這玩意兒能用。</p><h3 id="也不全是這樣子的" tabindex="-1">也不全是這樣子的 <a class="header-anchor" href="#也不全是這樣子的" aria-label="Permalink to “也不全是這樣子的”">​</a></h3><p>早在2002年的時候，我第一次安裝使用GNU/Linux，像大多數美國人那樣，我搞不定撥號連接，在我呆的這個小地方當時寬帶還沒普及。我在當地Best Buy商店裏花了差不多70美元買了用熱縮膜包裝的Mandrake 9.0的Powerpack版，當時那裏同時在賣Mandrake和Red Hat，現在仍然還在經營桌面PC業務。</p><p>在那個恐龍時代，Mandrake被認為是易用的Linux發行版中做的最好的。它安裝簡單，還有人説比Windows還簡單，它自帶的分區工具更是讓劃分磁盤像切蘋果餡餅一樣簡單。不過實際上，Linux老手們經常公開嘲笑Mandrake，暗示易用的Linux不是真的Linux。</p><p>但是我很喜歡它，感覺來到了一個全新的世界。再也不用擔心Windows的藍屏死機和幾乎每天一死了。不幸的是，之前在Windows下“能用”的很多外圍設備也隨之而去。</p>',9)),i("p",null,[n[4]||(n[4]=e("安裝完Mandrake之後我要做的第一件事就是，把我的小白盒拿給",-1)),a(t,{href:"http://www.dragonware.com/"},{default:o(()=>[...n[3]||(n[3]=[e("Dragonware Computers",-1)])]),_:1}),n[5]||(n[5]=e("的Michelle，把便宜的winmodem換成硬件調製解調器。就算是一個硬件貓意味着計算機響應更快，但是計算機商店卻在40英里外的地方，並不是很方便，而且費用對我也有點壓力。",-1))]),n[19]||(n[19]=r('<p>但是我不介意。我對Microsoft並不感冒－－而且使用一個“不同”的操作系統讓我感覺自己就像一個計算機天才。</p><p>打印機也是個麻煩，但是這個問題對於Mandrake還好，不像其他大多數發行版還需要命令列裏的操作才能解決。Mandrake提供了一個華麗的圖形界面來設置打印機－如果你正好幸運的有一台能在Linux下工作的打印機的話。很多打印機——就算不是大多數——都不行。</p><p>我的還在保修期的Lexmark，在Windows下比其他打印機多出很多華而不實的小功能，廠商並不支持Linux版本，但是我找到一個多少能用的開源逆向工程驅動。它能在Mozilla瀏覽器里正常打印網頁，但是在Star Office軟件裏打印的話會是用很小的字體塞到頁面的右上角里。打印機還會發出很大的機械響聲，讓我想起了汽車變速箱在報廢時發出的噪音。</p><p>Star Office問題的變通方案是把所有文字都保存到文本文件，然後在文本編輯器裏打印。而對於那個聽上去像是打印機處於天魔解體模式的噪音？我的方法是儘量不要打印。</p><h3 id="更多的其他問題-對我來説太多了都快忘了" tabindex="-1">更多的其他問題－對我來説太多了都快忘了 <a class="header-anchor" href="#更多的其他問題-對我來説太多了都快忘了" aria-label="Permalink to “更多的其他問題－對我來説太多了都快忘了”">​</a></h3><p>我肯定記得的一個問題是，聲卡工作不太正常，儘管Mandrake的界面上顯示檢測到並安裝了聲卡。泡了一段時間論壇也沒什麼收穫，最終有人建議可能是權限問題。我看了一下，我靠！被他説中了。Mandrake默認的聲卡權限不允許用户級別賬號的訪問，這也是在發行版發佈之前應該要修改掉的問題，就像Ken所説的。特別是在這種用熱縮膜包裝好的售價70美金的發行版－這在2002年可比現在值錢多了。</p><p>好吧，我還有個並口掃描儀，在我轉移到Linux之前兩個星期買的，之後它就基本是塊磚了，因為沒有Linux下的驅動。</p><p>我的觀點是在那個年代裏這些都不重要。我們大多數人都習慣了修改配置文件之類的事情，即便是運行微軟產品的“IBM兼容”計算機。就像那個年代的大多數用户，我剛學開始接觸使用命令列的DOS機器，在它上面打印機需要針對每個程序單獨設置，而且寫寫簡單的autoexec.bat是必備的技能。</p><p><img src="http://fossforce.com/wp-content/uploads/2014/08/Pontiac_GTO_1966-300x224.jpg" alt="Linux as a 1966 “goat.”"></p><p>Linux就像1966年的“山羊”</p><p>那時，能夠擺弄操作系統內部的配置是能夠擁有一台計算機的一個簡單部分。我們大多數使用計算機的人要麼是極客或是希望成為極客。我們為這種能夠調整計算機按我們想要的方式運行的能力而感到驕傲。我們就是那個年代裏高科技版本的好男孩，他們會在週六下午在樹蔭下改裝他們肌肉車上的排氣管，通風管，化油器之類的。</p><h3 id="不過現在大家不是這樣使用計算機的" tabindex="-1">不過現在大家不是這樣使用計算機的 <a class="header-anchor" href="#不過現在大家不是這樣使用計算機的" aria-label="Permalink to “不過現在大家不是這樣使用計算機的”">​</a></h3><p>現在的計算機用户只是希望它能幹活，不會有什麼問題。而不想知道為什麼Hulu或Netflix會不工作，或者為什麼有些程序裏字體顯示正常而有的卻沒有。在安裝完Linux後，他們不再希望聽到“噢，這只是個很容易修改的小問題”，就像是開着新買的Chevy在車流中打不上火歇菜了時，不想聽到“這只是個小問題我們會改的”。</p><p>現在，也包括我。儘管我很高興還有足夠的能力去修改從Mint或Fedora開發者漏過來的小問題，也不願去處理。我有自己的事情。而且在我不用工作的時候，寧願把時間浪費在Facebook上和朋友閒扯，也不想被自己的計算機搞得惱火。</p><p>當然，Linux隨着時間已經改變很多了。近幾年，可以完全肯定在筆記本電腦上安裝一個主流Linux發行版的時候，Wi-Fi肯定能用。而且，大多數時候你只需要把打印機插入USB端口中就好了，它就已經準備好並工作了。但是，仍然有許多小細節需要處理－一些很久很久之前就應該處理的東西。</p><p>也許Ken還得繼續抱怨下去...</p><hr>',17)),i("p",null,[n[7]||(n[7]=e("via: ",-1)),a(t,{href:"http://fossforce.com/2014/08/when-linux-was-perfect-enough/"},{default:o(()=>[...n[6]||(n[6]=[e("http://fossforce.com/2014/08/when-linux-was-perfect-enough/",-1)])]),_:1})]),i("p",null,[n[10]||(n[10]=e("作者：Christine Hall 譯者：",-1)),a(t,{href:"https://github.com/zpl1025"},{default:o(()=>[...n[8]||(n[8]=[e("zpl1025",-1)])]),_:1}),n[11]||(n[11]=e(" 校對：",-1)),a(t,{href:"https://github.com/wxy"},{default:o(()=>[...n[9]||(n[9]=[e("wxy",-1)])]),_:1})]),i("p",null,[n[14]||(n[14]=e("本文由 ",-1)),a(t,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...n[12]||(n[12]=[e("LCTT",-1)])]),_:1}),n[15]||(n[15]=e(" 原創翻譯，",-1)),a(t,{href:"http://linux.cn/"},{default:o(()=>[...n[13]||(n[13]=[e("Linux中國",-1)])]),_:1}),n[16]||(n[16]=e(" 榮譽推出",-1))])])}const P=p(d,[["render",x]]);export{C as __pageData,P as default};
